#!/usr/bin/env python3
"""Apply the first optional parallel execution checkpoint."""

from pathlib import Path
import base64
import gzip

FILES = {'Cargo.toml': '', 'PERFORMANCE_PLAN.md': '', '.github/workflows/rust.yml': '', 'src/error.rs': '', 'src/execution.rs': '', 'src/lib.rs': '', 'src/csr.rs': '', 'src/pcg.rs': '', 'tests/parallel.rs': ''}

for name, encoded in FILES.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(encoded)))

for temporary in [
    Path("scripts/apply_parallel_checkpoint.py"),
    Path(".github/workflows/apply-parallel-checkpoint.yml"),
]:
    temporary.unlink(missing_ok=True)
